def search(root, target):
    node = root
    while node:
        if target == node.val:
            return node
        node = node.left if target < node.val else node.right
    return None

def insert(root, val):
    if not root:
        return Node(val)
    node = root
    while True:
        if val < node.val:
            if not node.left:
                node.left = Node(val); return root
            node = node.left
        else:
            if not node.right:
                node.right = Node(val); return root
            node = node.right
    return root
```

Both are O(h), h = tree height — O(log n) for a balanced tree, degrading to O(n) for a skewed one. Neither needs recursion; both are naturally iterative since there's only ever one direction to go at each step.

```python
def delete(root, key):
    if not root:
        return None
    if key < root.val:
        root.left = delete(root.left, key)
    elif key > root.val:
        root.right = delete(root.right, key)
    else:
        if not root.left:
            return root.right
        if not root.right:
            return root.left
        successor = root.right
        while successor.left:
            successor = successor.left       # smallest value in right subtree
        root.val = successor.val             # copy successor's value up
        root.right = delete(root.right, successor.val)  # remove the successor itself
    return root
```

The **inorder successor** — the smallest value in the right subtree — is guaranteed to have at most one child (it's found by always going left, so it can't have a left child itself), which means deleting *it* afterward always falls into one of the two easy cases. Copying its value up preserves the invariant automatically, since the successor was already confirmed to be the smallest value greater than the deleted node.

